#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<double>validation={0.5,0.42,0.38,0.4,0.44,0.46};
    double best=1e100;
    int bestEpoch=-1,bad=0,patience=2;
    for (int epoch=0;epoch<int(validation.size());epoch++){
        if (validation[epoch]<best){
            best=validation[epoch];
            bestEpoch=epoch;
            bad=0;
        }
        else bad++;
        if (bad>=patience)break;
    }
    cout<<bestEpoch<<" "<<best<<"\n";
    return 0;
}

